using System.Drawing;

namespace Linter.Shell;

/// <summary>
/// Loads the icons embedded in the assembly (see <c>Assets\*.ico</c>,
/// generated by <c>tools/gen-assets.js</c>). Callers own the returned icon.
/// </summary>
internal static class AppIcons
{
    public const string On = "app.ico";
    public const string Off = "app-off.ico";

    public static Icon Load(string name, Size size)
    {
        using var stream = typeof(AppIcons).Assembly.GetManifestResourceStream($"Linter.Assets.{name}");
        // A missing resource is a build mistake, not a reason to refuse to start.
        return stream is null ? (Icon)SystemIcons.Application.Clone() : new Icon(stream, size);
    }
}
